class Solution {
public:
    vector<string> maxNumOfSubstrings(string s) {
        int first[26], last[26];
        fill(first, first+26, INT_MAX);
        fill(last, last+26, -1);
        int n = s.size();
        for (int i = 0; i < n; i++) {
            int c = s[i]-'a';
            first[c] = min(first[c], i);
            last[c] = i;
        }
        vector<string> res;
        int end = -1;
        for (int i = 0; i < n; i++) {
            if (i < end) continue;
            int j = i, k = i;
            bool ok = true;
            while (true) {
                int c = s[k]-'a';
                if (first[c] < i) { ok = false; break; }
                j = max(j, last[c]);
                if (k == j) break;
                k++;
            }
            if (ok) { res.push_back(s.substr(i, j-i+1)); end = j; }
        }
        return res;
    }
};

