        const c = s.charCodeAt(i) - 97;
        first[c] = Math.min(first[c], i);
        last[c] = i;
    }
    const cands = [];
    for (let i = 0; i < n; i++) {
        const c = s.charCodeAt(i) - 97;
        if (first[c] !== i) continue;
        let j = last[c], k = i, ok = true;
        while (k <= j) {
            const d = s.charCodeAt(k) - 97;
            if (first[d] < i) { ok = false; break; }
            j = Math.max(j, last[d]);
            k++;
        }
        if (ok) cands.push([j, -(j - i + 1), i]);
    }
    cands.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const res = [];
    let end = -1;
    for (const [r, , l] of cands) {
        if (l > end) {
            res.push(s.slice(l, r + 1));
            end = r;
        }
    }
    return res;
};
